import type { Interview } from "../types";

export function exportInterviewsPDF(interviews: Interview[], title = "Candidate Interviews Schedule"): boolean {
  const total = interviews.length;
  const completed = interviews.filter((i) => i.status === "completed").length;
  const scheduled = interviews.filter((i) => i.status === "scheduled").length;
  const cancelled = interviews.filter((i) => i.status === "cancelled").length;

  const rows = interviews.length > 0
    ? interviews
        .map((i) => {
          const candName = i.candidates?.full_name || "Candidate";
          const jobTitle = i.candidates?.job_postings?.title || "—";
          const sched = i.scheduled_at ? new Date(i.scheduled_at).toLocaleString() : "—";
          return `<tr>
            <td style="font-weight:700;color:#253C7D">${candName}</td>
            <td>${jobTitle}</td>
            <td>${sched}</td>
            <td>${i.duration_minutes || 45} mins</td>
            <td>${i.type}</td>
            <td>
              <span style="display:inline-block;padding:2px 8px;border-radius:6px;font-size:10px;font-weight:700;${
                i.status === "completed"
                  ? "background:#d1fae5;color:#065f46"
                  : i.status === "scheduled"
                  ? "background:#e0f2fe;color:#0369a1"
                  : "background:#fee2e2;color:#991b1b"
              }">${(i.status || "SCHEDULED").toUpperCase()}</span>
            </td>
            <td style="font-weight:700;text-align:center">${i.score ? `${i.score}/5` : "—"}</td>
          </tr>`;
        })
        .join("")
    : `<tr><td colspan="7" style="text-align:center;padding:24px;color:#64748b;">No scheduled interviews found.</td></tr>`;

  const html = `<!DOCTYPE html>
  <html>
  <head>
    <title>${title}</title>
    <style>
      @page { size: A4 landscape; margin: 15mm; }
      body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; margin: 0; padding: 24px; color: #1e293b; }
      .header-box { display: flex; justify-content: space-between; align-items: flex-start; border-bottom: 2px solid #253C7D; padding-bottom: 14px; margin-bottom: 18px; }
      h1 { font-size: 20px; font-weight: 800; color: #253C7D; margin: 0 0 4px 0; }
      .meta { font-size: 11px; color: #64748b; }
      .stats-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px; margin-bottom: 18px; }
      .stat-card { background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 10px; padding: 10px 14px; text-align: center; }
      .stat-val { font-size: 18px; font-weight: 800; color: #253C7D; }
      .stat-lbl { font-size: 10px; font-weight: 700; color: #64748b; text-transform: uppercase; margin-top: 2px; }
      table { width: 100%; border-collapse: collapse; margin-top: 8px; font-size: 11px; }
      th { text-align: left; padding: 8px 8px; background: #253C7D; color: #fff; font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.5px; }
      td { padding: 7px 8px; border-bottom: 1px solid #f1f5f9; }
      tr:nth-child(even) { background-color: #f8fafc; }
      .footer { margin-top: 24px; font-size: 10px; color: #94a3b8; display: flex; justify-content: space-between; border-top: 1px solid #e2e8f0; padding-top: 8px; }
    </style>
  </head>
  <body>
    <div class="header-box">
      <div>
        <h1>HRM_OPS — ${title}</h1>
        <div class="meta">Talent Acquisition &middot; Interview Assessment &amp; Evaluation Log</div>
      </div>
      <div class="meta" style="text-align:right">
        <div><strong>Generated:</strong> ${new Date().toLocaleString("en-US")}</div>
        <div><strong>Total Sessions:</strong> ${total} Interviews</div>
      </div>
    </div>

    <div class="stats-grid">
      <div class="stat-card"><div class="stat-val">${total}</div><div class="stat-lbl">Total Interviews</div></div>
      <div class="stat-card"><div class="stat-val" style="color:#059669">${completed}</div><div class="stat-lbl">Completed</div></div>
      <div class="stat-card"><div class="stat-val" style="color:#0284c7">${scheduled}</div><div class="stat-lbl">Scheduled / Upcoming</div></div>
      <div class="stat-card"><div class="stat-val" style="color:#dc2626">${cancelled}</div><div class="stat-lbl">Cancelled</div></div>
    </div>

    <table>
      <thead>
        <tr>
          <th>Candidate</th>
          <th>Position Applied</th>
          <th>Interview Date &amp; Time</th>
          <th>Duration</th>
          <th>Type</th>
          <th>Status</th>
          <th style="text-align:center">Score</th>
        </tr>
      </thead>
      <tbody>${rows}</tbody>
    </table>

    <div class="footer">
      <div>HRM_OPS Enterprise HRMS &middot; Candidate Evaluation</div>
      <div>Page 1 of 1</div>
    </div>
  </body>
  </html>`;

  const w = window.open("", "_blank");
  if (w) {
    w.document.write(html);
    w.document.close();
    setTimeout(() => w.print(), 400);
  }
  return true;
}
