import { useState, useEffect, useCallback } from "react";
import { supabase } from "@/lib/supabase";
import { toast } from "@/components/Toast";
import { useBranchScope } from "@/context/BranchContext";
import { usePermissions } from "@/hooks/usePermissions";
import type { Job, Candidate, Interview, Branch, HiringRequest } from "../types";

export function useHireData() {
  const {
    isSuperAdmin,
    isBranchAdmin,
    effectiveBranchId,
    userBranchId,
    userBranchName,
    targetBranch,
    isPartnerBranchBlocked,
    visibleBranches,
  } = useBranchScope();
  const { role, isAdmin } = usePermissions();

  const isHrDivisionBranch = /hr|human\s*resource|headquarter/i.test(userBranchName || "") || isSuperAdmin;
  const canHrReview =
    !!role?.hiring_requests_hr_review ||
    /hr\s*manager|hr\s*staff|recruiter/i.test(role?.name || "") ||
    (isHrDivisionBranch && (isBranchAdmin || isAdmin || isSuperAdmin));

  const [jobs, setJobs] = useState<Job[]>([]);
  const [candidates, setCandidates] = useState<Candidate[]>([]);
  const [interviews, setInterviews] = useState<Interview[]>([]);
  const [branches, setBranches] = useState<Branch[]>([]);
  const [hiringRequests, setHiringRequests] = useState<HiringRequest[]>([]);
  const [loading, setLoading] = useState(true);

  const loadData = useCallback(async () => {
    if (isPartnerBranchBlocked || (!isSuperAdmin && !userBranchId)) {
      setJobs([]);
      setCandidates([]);
      setInterviews([]);
      setBranches([]);
      setHiringRequests([]);
      setLoading(false);
      return;
    }

    setLoading(true);
    try {
      let jobQuery = supabase
        .from("job_postings")
        .select("*, branches(id, name)")
        .is("deleted_at", null)
        .order("posted_at", { ascending: false });

      // HR Division, HR Reviewers, and SuperAdmins have enterprise-wide recruitment authority
      // (managing jobs, candidates, interviews, and candidate files across all branches).
      // Regular branch managers are scoped to their own branch's vacancies.
      if (targetBranch && !isSuperAdmin && !canHrReview && !isHrDivisionBranch) {
        jobQuery = jobQuery.or(`branch_id.eq.${targetBranch},branch_id.is.null`);
      }

      const branchQuery = supabase.from("branches").select("id, name").is("deleted_at", null).order("name");

      let reqQuery = supabase
        .from("hiring_requests")
        .select("*, branches(id, name)")
        .is("deleted_at", null)
        .order("created_at", { ascending: false });

      // If user is not HR reviewer or SuperAdmin, scope to their branch.
      // HR Division / HR reviewers see all branch requests requiring review.
      if (targetBranch && !isSuperAdmin && !canHrReview && !isHrDivisionBranch) {
        reqQuery = reqQuery.or(`branch_id.eq.${targetBranch},branch_id.is.null`);
      }

      const [{ data: j }, { data: c }, { data: i }, { data: b }, { data: hr }] = await Promise.all([
        jobQuery,
        supabase
          .from("candidates")
          .select("*, job_postings(id, title, department, branch_id)")
          .is("deleted_at", null)
          .order("applied_at", { ascending: false }),
        supabase
          .from("interviews")
          .select(
            "*, candidates(id, full_name, job_posting_id, job_postings(title, department, branch_id)), employees(id, first_name, last_name, avatar_url, branch_id)"
          )
          .is("deleted_at", null)
          .order("scheduled_at", { ascending: false }),
        branchQuery,
        reqQuery,
      ]);

      const rawJobs = (j as unknown as Job[]) || [];
      const jobIds = new Set(rawJobs.map((x) => x.id));

      const filteredCandidates = ((c as unknown as Candidate[]) || []).filter(
        (cand) => cand.job_posting_id && jobIds.has(cand.job_posting_id)
      );

      const candIds = new Set(filteredCandidates.map((x) => x.id));

      const filteredInterviews = ((i as unknown as Interview[]) || []).filter(
        (iv) => candIds.has(iv.candidate_id)
      );

      setJobs(rawJobs);
      setCandidates(filteredCandidates);
      setInterviews(filteredInterviews);

      const allBranches = visibleBranches && visibleBranches.length > 0
        ? (visibleBranches as Branch[])
        : ((b as unknown as Branch[]) || []);

      const currentBranchId = targetBranch || effectiveBranchId;
      const scopedList = currentBranchId
        ? allBranches.filter((br) => br.id === currentBranchId || br.branch_id === currentBranchId)
        : allBranches;

      setBranches(scopedList.length > 0 ? scopedList : allBranches);
      setHiringRequests((hr as unknown as HiringRequest[]) || []);
    } catch (err) {
      console.error("Error loading hire data:", err);
      toast("Error", "Failed to load recruitment data", "error");
    } finally {
      setLoading(false);
    }
  }, [isPartnerBranchBlocked, targetBranch, effectiveBranchId, userBranchId, visibleBranches, isSuperAdmin, canHrReview, isHrDivisionBranch]);

  useEffect(() => {
    loadData();
  }, [loadData]);

  return {
    isPartnerBranchBlocked,
    userBranchId,
    userBranchName,
    targetBranch,
    jobs,
    setJobs,
    candidates,
    setCandidates,
    interviews,
    setInterviews,
    branches,
    hiringRequests,
    setHiringRequests,
    loading,
    loadData,
  };
}
